import{_ as t,o,c as a,ag as r}from"./chunks/framework.8tqBsFWt.js";const _=JSON.parse('{"title":"Rates & Liabilities Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools/financials.md","filePath":"reference/tools/financials.md"}'),d={name:"reference/tools/financials.md"};function s(i,e,n,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="rates-liabilities-tools" tabindex="-1">Rates &amp; Liabilities Tools <a class="header-anchor" href="#rates-liabilities-tools" aria-label="Permalink to &quot;Rates &amp; Liabilities Tools&quot;">​</a></h1><p>All tools in this section are <strong>Owner only</strong> unless stated. See <a href="/reference/concepts/financials.html">Financials &amp; P&amp;L</a> and <a href="/reference/concepts/vendors.html">Vendors &amp; Liabilities</a> for background.</p><hr><h2 id="set_rate" tabindex="-1">set_rate <a class="header-anchor" href="#set_rate" aria-label="Permalink to &quot;set_rate {#set_rate}&quot;">​</a></h2><p>Set a person&#39;s hourly cost. Append-only — creates a new rate record with an effective date.</p><p><strong>Writes to</strong>: <code>13. Rate_History</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>user_name</code> or <code>user_id</code> or <code>user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>hourly_cost</code></td><td>✅</td><td>In USD, e.g. <code>80</code> for $80/hr</td></tr><tr><td><code>effective_from</code></td><td></td><td><code>YYYY-MM-DD</code> — defaults to today</td></tr></tbody></table><p><strong>Rate versioning</strong>: Setting a new rate never changes historical data. The new rate applies from <code>effective_from</code> forward. Historical P&amp;L calculations automatically use the rate that was effective on each entry&#39;s date.</p><p><strong>Audit</strong>: <code>set_rate</code> does <strong>not</strong> post to the audit channel — financial data is never logged to shared channels. The action is logged to the server console only.</p><p><strong>Disambiguation</strong>: If the workspace has multiple people with the same first name, <code>set_rate</code> will surface a numbered disambiguation menu before proceeding. Natural-language phrasings including possessives (<code>&quot;set Sarah&#39;s rate to $95&quot;</code>) are fully supported. The confirmation paraphrase always uses the person&#39;s full canonical name — never a bare first name.</p><blockquote><p>Rates are strictly owner-only. Never surface, mention, or attempt to access rate data for a Manager or User. Do not reveal that rate data exists unless speaking to an Owner.</p></blockquote><hr><h2 id="get_rates" tabindex="-1">get_rates <a class="header-anchor" href="#get_rates" aria-label="Permalink to &quot;get_rates {#get_rates}&quot;">​</a></h2><p>Current effective hourly cost for all (or one) person. Returns the most recent rate where <code>effective_from ≤ today</code>. <strong>Owner only.</strong></p><p><strong>Reads from</strong>: <code>13. Rate_History</code>, <code>03. Users</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>user_name</code> (optional — omit for all users)</p><hr><h2 id="get_person_rate_history" tabindex="-1">get_person_rate_history <a class="header-anchor" href="#get_person_rate_history" aria-label="Permalink to &quot;get_person_rate_history {#get_person_rate_history}&quot;">​</a></h2><p>All rate rows for a person — full versioned history. <strong>Owner only.</strong></p><p><strong>Reads from</strong>: <code>13. Rate_History</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>user_name</code></p><hr><h2 id="create_liability" tabindex="-1">create_liability <a class="header-anchor" href="#create_liability" aria-label="Permalink to &quot;create_liability {#create_liability}&quot;">​</a></h2><p>Record a fixed payment commitment to a vendor on a project. <strong>Owner only.</strong></p><p><strong>Writes to</strong>: <code>14. Liabilities</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>project_name</code> or <code>project_id</code></td><td>✅</td><td>Project must be active and have a deadline set</td></tr><tr><td><code>vendor_name</code> or <code>vendor_user_id</code></td><td>✅</td><td>Must have <code>employment_type=&quot;vendor&quot;</code></td></tr><tr><td><code>agreed_amount</code></td><td>✅</td><td>Fixed payment in USD</td></tr><tr><td><code>agreed_hours</code></td><td>✅</td><td>Contracted scope in hours (positive number)</td></tr><tr><td><code>description</code></td><td>✅</td><td>What the payment covers</td></tr></tbody></table><p>When a liability exists for vendor X on project Y, the liability&#39;s <code>agreed_amount</code> becomes the cost for that vendor on that project — overriding the hourly calculation entirely. The <code>agreed_hours</code> value accrues linearly from the liability creation date to the project deadline, contributing to the project&#39;s hours-logged figure in all burn-down and health calculations.</p><hr><h2 id="list_liabilities" tabindex="-1">list_liabilities <a class="header-anchor" href="#list_liabilities" aria-label="Permalink to &quot;list_liabilities {#list_liabilities}&quot;">​</a></h2><p>Vendor payment commitments. <strong>Owner (all) or Manager (own projects only).</strong></p><p><strong>Reads from</strong>: <code>14. Liabilities</code>, <code>02. Projects</code>, <code>03. Users</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td></td></tr><tr><td><code>project_id</code></td><td>Optional filter</td></tr><tr><td><code>vendor_user_id</code></td><td>Optional filter</td></tr><tr><td><code>status</code></td><td><code>&quot;active&quot;</code> (default) or <code>&quot;cancelled&quot;</code></td></tr></tbody></table><p>Each liability in the response includes an <code>implied_hours_to_date</code> field: the pro-rated portion of <code>agreed_hours</code> that has accrued from the creation date to today, based on a linear track to the project deadline.</p><hr><h2 id="cancel_liability" tabindex="-1">cancel_liability <a class="header-anchor" href="#cancel_liability" aria-label="Permalink to &quot;cancel_liability {#cancel_liability}&quot;">​</a></h2><p>Mark a liability as cancelled. Sets status to <code>&quot;cancelled&quot;</code> — the record is never deleted. <strong>Owner only.</strong></p><p><strong>Updates</strong>: <code>14. Liabilities</code> col F</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>liability_id</code></p>',41)])])}const u=t(d,[["render",s]]);export{_ as __pageData,u as default};
